// «Monitoring турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

const responses = [
  { status: 200 }, { status: 200 }, { status: 500 }, { status: 200 }, { status: 503 },
  { status: 200 }, { status: 200 }, { status: 200 }, { status: 200 }, { status: 200 },
];

window.RATE = null;
window.RATE_EMPTY = null;
try {
  window.RATE = errorRate(responses);
  window.RATE_EMPTY = errorRate([]);
  panel(window.RATE < 0.5 ? "ok" : "bad", "rate", "Алдааны хувь", ["errorRate → " + window.RATE, "хоосон → " + window.RATE_EMPTY]);
} catch (problem) {
  panel("bad", "error", "Алдаа", [problem.message]);
}
document.body.dataset.ready = "1";

